# Analyze both demos for pattern transformation
def analyze_demo(name, inp, out):
    print(f"\n=== ANALYZING DEMO: {name} ===")

    # Find background (most common value)
    bg_counts = {}
    for row in inp:
        for v in row:
            bg_counts[v] = bg_counts.get(v, 0) + 1
    bg = max(bg_counts, key=bg_counts.get)
    print(f"Background: {bg}")

    # Find base row (full row of one color)
    for i, row in enumerate(inp):
        if len(set(row)) == 1 and row[0] != bg:
            print(f"Base color: {row[0]} (row {i})")
            break

    # Find pattern (non-bg, non-base)
    pattern_rows = []
    pattern_cols = set()
    for i, row in enumerate(inp):
        for j, v in enumerate(row):
            if v != bg and v != row[0] if len(set(row)) == 1 else True:  # Not base row
                if v != bg:
                    pattern_rows.append(i)
                    pattern_cols.update([j for j, x in enumerate(row) if x != bg])
    if pattern_rows:
        pattern_start = min(pattern_rows)
        pattern_end = max(pattern_rows)
        pattern_rows = list(range(pattern_start, pattern_end + 1))
        pattern_width = max(pattern_cols) + 1 if pattern_cols else 0
        print(f"Pattern rows: {pattern_rows}, width: {pattern_width}")
        for i in pattern_rows:
            print(f"  Row {i}: non-bg = {[x for x in inp[i] if x != bg]}")

    print(f"\nOutput pattern:")
    for i, row in enumerate(out):
        if any(x != bg for x in row):
            print(f"  Row {i}: {[x for x in out[i] if x != bg]}")

