for i, row in enumerate(out_exp):
    if row != [9]*4:
        print(f"Row {i}: {row}")

# Test transform
def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]

    base_row = -1
    base_color = None
    for i in range(h):
        row = grid[i]
        if all(c == row[0] for c in row) and row[0] != bg:
            base_row = i
            base_color = row[0]
            break

    pattern_rows = []
    for i in range(h):
        if i != base_row:
            row = grid[i]
            if any(c != bg and c != base_color for c in row):
                pattern_rows.append((i, row))

    if not pattern_rows:
        return grid

    output = [[bg] * w for _ in range(h)]
    output[base_row] = list(grid[base_row])

    if pattern_rows:
        top_pattern_row = pattern_rows[0][0]
        for i, row in pattern_rows:
            new_i = i + 1
            if new_i <= base_row:
                output[new_i] = list(row)
        output[top_pattern_row] = [8] * w

    return output

out_actual = transform(inp)

print("\n=== Demo 2 ACTUAL OUTPUT ===")
